src='''from collections import deque


def transform(grid):
    height, width = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(height):
        for c in range(width):
            if not grid[r][c] or (r, c) in seen:
                continue
            color = grid[r][c]
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                y, x = queue.popleft()
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < height and 0 <= nx < width and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        cells.add((ny,nx))
                        queue.append((ny,nx))
            top = min(y for y, x in cells)
            left = min(x for y, x in cells)
            bottom = max(y for y, x in cells)
            right = max(x for y, x in cells)
            local = {(y-top, x-left) for y, x in cells}
            frame = (all((0, x) in local and (bottom-top, x) in local for x in range(right-left+1))
                     and all((y, 0) in local and (y, right-left) in local for y in range(bottom-top+1))
                     and len(local) == 2*(bottom-top+1) + 2*(right-left+1) - 4)
            objects.append({"cells": cells, "color": color, "top": top, "left": left,
                            "bottom": bottom, "frame": frame})

    out = [[0] * width for _ in range(height)]
    placed = {True: [], False: []}

    def shift_obj(obj, dy):
        return {(y + dy, x) for y, x in obj["cells"]}

    def collides(cells, group):
        return any(cells & other for other in group)

    # Frames settle upward. Objects that began higher settle first.
    for obj in sorted((o for o in objects if o["frame"]), key=lambda o: o["top"]):
        dy = 0
        while min(y for y, x in shift_obj(obj, dy)) > 0 and not collides(shift_obj(obj, dy - 1), placed[True]):
            dy -= 1
        cells = shift_obj(obj, dy)
        placed[True].append(cells)
        for y, x in cells:
            out[y][x] = obj["color"]

    # Cross-shaped objects settle downward. Objects that began lower settle first.
    for obj in sorted((o for o in objects if not o["frame"]), key=lambda o: o["bottom"], reverse=True):
        dy = 0
        while max(y for y, x in shift_obj(obj, dy)) < height - 1 and not collides(shift_obj(obj, dy + 1), placed[False]):
            dy += 1
        cells = shift_obj(obj, dy)
        placed[False].append(cells)
        for y, x in cells:
            out[y][x] = obj["color"]
    return out
'''
